mapper.update:
update bus_gd_pf_info set cash_bonus = #{cashBonus},bonus_issue = #{bonusIssue}
where
gd_pid = #{gdPid} and gd_type = #{gdType}

mapper.select:
select * from (select a.pid as pid,a.pf_pid as pfPid,a.gd_pid as gdPid,a.gd_type as gdType,a.sharehold_code as shareholdCode,a.trade_account as tradeAccount, a.hole_share_amount as holeShareAmount,a.shareholding_proportion as shareholdingProportion,a.frozen_share_amount as frozenShareAmount,a.pledged_share_amount as pledgedShareAmount, a.cash_bonus as cashBonus,a.bonus_issue as bonusIssue,b.name_,null as stateOwned,b.identify_type as identifyType,b.identify_number as identifyNumber,b.domestic_or_foreign as domesticOrForeign from bus_gd_pf_info a join bus_rel_psn b on a.sharehold_code = b.shareholders_code where a.gd_type = 'PSN' union ALL select a.pid as pid,a.pf_pid as pfPid,a.gd_pid as gdPid,a.gd_type as gdType,a.sharehold_code as shareholdCode,a.trade_account as tradeAccount,a.hole_share_amount as holeShareAmount,a.shareholding_proportion as shareholdingProportion,a.frozen_share_amount as frozenShareAmount, a.pledged_share_amount as pledgedShareAmount,a.cash_bonus as cashBonus,a.bonus_issue as bonusIssue,b.org_name as name_,b.state_owned as stateOwned,b.identify_type as identifyType, b.unisc_code as identifyNumber,b.domestic_or_foreign as domesticOrForeign from bus_gd_pf_info a join bus_rel_org b on a.sharehold_code = b.shareholders_code where a.gd_type = 'ORG') where 1=1 and pfPid = #{pfPid}
and shareholdCode = #{shareholdCode}
and name_ = #{name_}
and domesticOrForeign = #{domesticOrForeign}
